  mat *= trans(vec3(0, 0, pow(s, 2.)));


  gl_Position = mat * vec4(pos, 1);
  vec3 n = normalize((mat * vec4(normal, 0)).xyz);

  vec3 lightDir = normalize(vec3(0.3, 0.4, -1));

    float hue = mix(0.9, 1.1, s) + time * 0.1;
    float sat = mix(.0, 1., pow(s, 5.));
