    //v_color = vec4(color * pinch(lt, 2.), 1);
    v_color = vec4(color * lt, 1);
    v_color.a = mix(-.2, 0.2, pow(s, 3.));
    v_color.rgb *= v_color.a; 
    if (v_color.a <= -.10) {
      gl_Position.z = 10000.;
    }
  #if 0
