float easeInOutSine(float t) {
  return (-0.5 * (cos(PI * t) - 1.));
}

float mixer(float t, float timeOff, float duration) {
  t = mod(t, duration * 2.0);
  t = t - timeOff;
  if (t > duration) {
    t = duration + 1. - t;
  }
  return easeInOutSine(clamp(t, 0., 1.));
}

