  float cu = cx / (across - 1.);
  float cv = cy / (down - 1.);
  float cw = cz / (back - 1.);

  float ca = cu * 2. - 1.;
  float cb = cv * 2. - 1.;
  float cc = cw * 2. - 1.;

  float sv1 = atan(ca, cb) / PI;
  float sv = abs(atan(sv1, cc)) / PI;


  float s1 = texture2D(sound, vec2(mix(0.01, 0.5, (sv)), 0. / soundRes.y)).a;
  float s2 = texture2D(sound, vec2(mix(0.01, 0.5, (sv)), 1. / soundRes.y)).a;
  float s3 = texture2D(sound, vec2(mix(0.01, 0.5, (sv)), 2. / soundRes.y)).a;
  float s4 = texture2D(sound, vec2(mix(0.01, 0.5, (sv)), 3. / soundRes.y)).a;
  float s = (s1 + s2 + s3 + s4) / 4.;

  s = mix(0., 1. + sv * .3, s);
