  mat4 wmat = rotY(time * 0.1); 
  wmat *= rotX(sin(time * 0.13));
  wmat *= trans(vec3(ca, cc, cb) * down * 0.65);
  wmat *= uniformScale(clamp(mix(-.2, 9., pow(s, 6.)), 0., 1.));

  vec4 wpos = wmat * vec4(pos, 1);
  gl_Position = pmat * vmat * wpos;
  vec3 n = normalize((wmat * vec4(normal, 0)).xyz);

  //vec3 lightDir = normalize(vec3(0.3, 0.4, -1));
  vec3 lightPos = vec3(34, 3, -24);
