  float val = mix(0.5, 0.5, step(0.8, s));
  vec3 color = hsv2rgb(vec3(hue, sat, val));
  float lt  = dot(n, lightDir) * 0.5 + 0.5;
  v_color = vec4(color * pinch(lt, 2.) + vec3(pow(lt, 200.)), 1);
}

