float easeInOutCubic(float pos) {
  if (pos < 0.5) {
    return 0.5 * pow(pos / 0.5, 3.);
  }
  pos -= 0.5;
  pos /= 0.5;
  pos  = 1. - pos;
  return (1. - pow(pos, 3.)) * 0.5 + 0.5;
}

float inOut(float v) {
  float t = fract(v);
  if (t < 0.5) {
    return easeInOutCubic(t / 0.5);
  }
  return easeInOutCubic(2. - t * 2.);
}

