    vCubeOrigin = vec3(hash(fCubeId), hash(fCubeId * 0.371), hash(fCubeId *  0.781)) * 2. - 1.;
    vCubeOrigin *= 0.0 + pow(snd, 5.) * 30.0;

    mat  = ident();
    mat *= trans(vCubeOrigin);
